                </a>
                <Link href="/contact">
                  <BrutalistButton
                    variant="dark"
                    size="lg"
                    icon={<ArrowRight className="w-5 h-5" />}
                  >
                    {t("albumsCta.buttonSecondary")}
                  </BrutalistButton>
                </Link>
              </div>
            </NeoCard>
          </div>
        </section>
      </main>

      <NeoFooter />
    </div>
  );
};

export default NeoAlbumsPage;

